const crypto = require('node:crypto');

function createAccess(secure) {
  const sessions = new Map();
  const lifetime = 8 * 60 * 60 * 1000;
  function read(req) {
    const token = (req.headers.cookie || '').match(/(?:^|;\s*)cr_session=([a-f0-9]{64})(?:;|$)/)?.[1];
    const active = sessions.get(token);
    if (active && active.until > Date.now()) return active.credential;
    sessions.delete(token);
  }
  function start(req, res, credential) {
    close(req, res);
    for (const [token, session] of sessions) if (session.until <= Date.now()) sessions.delete(token);
    if (sessions.size >= 256) sessions.delete(sessions.keys().next().value);
    const token = crypto.randomBytes(32).toString('hex');
    sessions.set(token,{credential,until:Date.now()+lifetime});
    res.setHeader('Set-Cookie',cookie(token,lifetime/1000));
  }
  function cookie(value,maxAge) {
    return 'cr_session='+value+'; Path=/; HttpOnly; SameSite=Strict; Max-Age='+maxAge+(secure?'; Secure':'');
  }
  function close(req,res) {
    const token = (req.headers.cookie || '').match(/(?:^|;\s*)cr_session=([a-f0-9]{64})(?:;|$)/)?.[1];
    sessions.delete(token);
    res.setHeader('Set-Cookie',cookie('',0));
  }
  return {read,start,close};
}
async function credential(req){
  if (!(req.headers['content-type']||'').startsWith('application/x-www-form-urlencoded'))throw Error('Formulário inválido.');
  let body='';
  for await(const chunk of req){body+=chunk;if(body.length>8192)throw Error('Formulário inválido.');}
  const form=new URLSearchParams(body), user=form.get('login'), password=form.get('password');
  if(!user||!password||user.length>64||password.length>256||user.includes(':')) throw Error('Confira o usuário e a senha.');
  return 'Basic '+Buffer.from(user+':'+password).toString('base64');
}

const loginPhotos = [{"src": "data:image/webp;base64,", "credit": "Karina m roque · CC BY-SA 3.0", "source": "https://commons.wikimedia.org/wiki/File:Por_do_Sol_Praia_das_Conchas_Itacar%C3%A9.jpeg"}, {"src": "data:image/webp;base64,", "credit": "Marinelson Almeida Silva · CC BY 2.0", "source": "https://commons.wikimedia.org/wiki/File:Praia_de_Itacar%C3%A9zinho_-_Itacar%C3%A9_-_Bahia_-_Brasil_(8552602430).jpg"}, {"src": "data:image/webp;base64,", "credit": "LíviaBuhring · CC BY-SA 3.0", "source": "https://commons.wikimedia.org/wiki/File:Itacar%C3%A9_Praia_Cidade.JPG"}];

function rotateLoginPhoto(photos, retry) {
  const key = 'casa-rosa-login-photo';
  let index = 0;
  try {
    const previous = Number(localStorage.getItem(key) ?? -1);
    if (Number.isInteger(previous) && previous >= 0 && previous < photos.length) {
      index = retry ? previous : (previous + 1) % photos.length;
    }
    localStorage.setItem(key, String(index));
  } catch {
    index = Math.floor(Math.random() * photos.length);
  }
  const photo = photos[index];
  document.body.style.backgroundImage = 'linear-gradient(#340e2540,#340e2540),url("' + photo.src + '")';
  const credit = document.querySelector('#login-photo-credit');
  credit.href = photo.source;
  credit.textContent = 'Foto de ' + photo.credit;
  credit.hidden = false;
}

function loginPage(action='/entrar',mode='login',error=''){
  const setup=mode==='setup', link=mode==='link';
  return '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Casa Rosa ERP</title>'+
    '<style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f8edf3;color:#40152e;font:16px system-ui}main{width:min(380px,calc(100vw - 88px));padding:28px;background:white;border-radius:20px}label,input,button{display:block;width:100%;box-sizing:border-box}input,button{padding:12px;margin:6px 0 18px;border:1px solid #bc9caf;border-radius:8px;font:inherit}button{background:#74274f;color:white;cursor:pointer}p{line-height:1.45}a{color:#74274f}body.login-photo{box-sizing:border-box;padding:24px 16px 52px;position:relative;background-size:cover;background-position:center}body.login-photo main{box-shadow:0 12px 44px #2106194d}#login-photo-credit{position:absolute;bottom:12px;left:16px;color:white;background:#24131e;padding:5px 9px;border-radius:6px;font-size:12px}</style>'+
    '<body'+(mode==='login'?' class="login-photo"':'')+'><main><h1>Casa Rosa ERP</h1><h2>'+(setup?'Criar administrador local':link?'Vincular à nuvem':'Entrar')+'</h2>'+
    (setup?'<p>Defina seu usuário e uma senha de pelo menos 10 caracteres. Você pode fazer isso sem internet.</p>':'')+
    (error?'<p role="alert">'+error+'</p>':'')+'<form method="post" action="'+action+'">'+
    '<label>Usuário<input name="login" autocomplete="username" required maxlength="64"></label>'+
    '<label>Senha<input type="password" name="password" autocomplete="'+(setup?'new-password':'current-password')+'" required maxlength="256" '+(setup?'minlength="10"':'')+'></label>'+
    '<button>'+(setup?'Criar e entrar':link?'Vincular':'Entrar')+'</button></form>'+(link?'<a href="/">Voltar ao ERP</a>':'')+'</main>'+
    (mode==='login'?'<a id="login-photo-credit" target="_blank" rel="noopener noreferrer" hidden></a><script>('+rotateLoginPhoto.toString()+')('+JSON.stringify(loginPhotos)+','+Boolean(error)+');</script>':'')+
    '</body></html>';
}
module.exports={createAccess,credential,loginPage};
